#include <stddef.h>
double average(const int *values, size_t count);   /* prototype. */
void reset(void);                                   /* explicitly no parameters. */

/* stats.c: the one definition. */
#include "stats.h"
double average(const int *values, size_t count) {
    if (count == 0) return 0.0;
    long sum = 0;
    for (size_t i = 0; i < count; i++) sum += values[i];
    return (double)sum / count;
}

/* main.c */
#include <stdio.h>
#include "stats.h"
int main(void) {
    int marks[] = {7, 9, 8};
    printf("%.2f\n", average(marks, 3));   /* 8.00. */
    /* average(marks);  error: too few arguments. */
    return 0;
}
